110	 */
111	public class ApplyClaimStatus {
112	    public void apply(@Val Claim claim, @Val ClaimStatusChange change, PersonRepository people, RateRepository rates,
113	            PeriodRepository periods, SettingRepository settings, RoleRepository roles, SheetRepository sheets, Out<Claim> changed, Out<ClaimNumber> number) throws InvalidClaimStatusException {
114	        boolean allowed = switch (change.to()) {
115	            case OPEN -> claim.status() == ClaimStatus.DRAFT;
116	            case SETTLED -> claim.status() == ClaimStatus.OPEN;
117	            case VOID -> claim.status() == ClaimStatus.DRAFT || claim.status() == ClaimStatus.OPEN;
118	            case DRAFT -> false;
119	        };
120	        if (!allowed) {
121	            throw new InvalidClaimStatusException("A " + claim.status() + " claim cannot be made " + change.to());
122	        }
123	        if (periods.closedOn(claim.sheetId(), claim.date())) {
124	            throw new InvalidClaimStatusException("The claim's date is inside a closed period");
125	        }
126	        if (change.to() == ClaimStatus.SETTLED && change.by().equals(claim.openedBy())) {
127	            throw new InvalidClaimStatusException("The user who opened a claim cannot settle it");
128	        }
129	        BigDecimal settledDue = change.to() == ClaimStatus.SETTLED ? LateCharge.of(claim.sheetId(), sheets, settings).add(claim, due(claim, people, rates, settings)) : claim.due();
130	        if (change.to() == ClaimStatus.SETTLED && settledDue != null
131	                && !RoleRepository.STEWARD.equals(roles.roleOf(claim.sheetId(), change.by()))) {
132	            BigDecimal limit = settings.clerkLimit(claim.sheetId());
133	            if (limit != null && settledDue.compareTo(limit) > 0) {
134	                throw new InvalidClaimStatusException("A clerk cannot settle a claim whose due is above the clerk limit");
135	            }
136	        }
137	        number.set(new ClaimNumber(claim.number()));
138	        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
139	                claim.note(), change.to(), claim.number(), settledDue,
140	                change.to() == ClaimStatus.OPEN ? change.by() : claim.openedBy(), claim.stated(), claim.statedDue()));
141	    }
142	
143	    private static BigDecimal due(Claim claim, PersonRepository people, RateRepository rates, SettingRepository settings) {
144	        if (claim.stated()) {
145	            return claim.statedDue();
146	        }
147	        Person person = people.find(claim.sheetId(), claim.personId());
148	        return person == null ? null : ClaimDue.live(claim, person.gradeOn(claim.date()), rates, settings.floor(claim.sheetId()));
149	    }
