491	/**
492	 * The late charge on a sheet as of its today: an overdue claim (OPEN, its due-by — its date plus the terms — before
493	 * today) gains the late percent of its figure for every full 30 days it is overdue, rounded half to even to two
494	 * decimals. The charge is never bound by a statement (it follows today); settling freezes it into the claim's due.
495	 */
496	public record LateCharge(LocalDate today, int terms, BigDecimal pct) {
497	
498	    /** The days in each step of the charge. */
499	    public static final int DAYS = 30;
500	
501	    public static LateCharge of(String sheetId, SheetRepository sheets, SettingRepository settings) {
502	        return new LateCharge(sheets.today(sheetId), settings.terms(sheetId), settings.latePct(sheetId));
503	    }
504	
505	    /** The charge on the claim with the given figure: zero when it is not overdue a full 30 days or has no figure. */
506	    public BigDecimal on(Claim claim, BigDecimal figure) {
507	        if (figure == null || claim.status() != ClaimStatus.OPEN || claim.due() != null) {
508	            return BigDecimal.ZERO.setScale(2);
509	        }
510	        long overdue = ChronoUnit.DAYS.between(claim.date().plusDays(terms), today);
511	        long steps = overdue <= 0 ? 0 : overdue / DAYS;
512	        return figure.multiply(pct).multiply(BigDecimal.valueOf(steps)).movePointLeft(2)
513	                .setScale(2, RoundingMode.HALF_EVEN);
514	    }
515	
516	    /** The figure with its charge added on top; null when it has none. */
517	    public BigDecimal add(Claim claim, BigDecimal figure) {
518	        return figure == null ? null : figure.add(on(claim, figure));
